<?php
namespace ZinCelestial\Platform\Audit;use RuntimeException;defined('ABSPATH')||exit;
final class AuditRetentionService{public function __construct(private \wpdb $db,private string $audit_table,private string $export_table,private int $site_id){}public function purge(AuditRetentionPolicy $policy,int $now,string $approval_id):int{if(!preg_match('/^[a-zA-Z0-9_-]{8,191}$/',$approval_id))throw new RuntimeException('Retention approval required.');$cutoff=gmdate('Y-m-d H:i:s',$policy->deletable_before($now));if($policy->require_verified_export){$ok=$this->db->get_var($this->db->prepare("SELECT export_id FROM {$this->export_table} WHERE site_id=%d AND verified=1 AND through_at>=%s ORDER BY through_at DESC LIMIT 1",$this->site_id,$cutoff));if(!$ok)throw new RuntimeException('Verified audit export required.');}$this->db->query('START TRANSACTION');try{$n=$this->db->query($this->db->prepare("DELETE FROM {$this->audit_table} WHERE site_id=%d AND created_at<%s AND legal_hold=0",$this->site_id,$cutoff));if($n===false)throw new RuntimeException('Audit retention purge failed.');$this->db->query('COMMIT');return(int)$n;}catch(\Throwable $e){$this->db->query('ROLLBACK');throw$e;}}}
